}

/* ---- Solution ---- */
.street {
  display: grid;
  justify-items: center;
}

.light {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  width: 80px;
  padding: 16px 0;
  border-radius: 20px;
}

.lamp {
  width: 48px;
  height: 48px;
  border-radius: 50%;
}

.red,
.amber {
  opacity: 0.3;
}

.green {
  box-shadow: 0 0 24px 6px rgb(34 197 94 / 0.7);
}

.pole {
  width: 16px;
  height: 120px;
}
